#!/usr/bin/env python3
"""Build Aurelion's bundled campaign from the corrected source manifest; does not alter other campaigns."""
import json,html
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
SOURCE=ROOT/'campaigns/aurelion-the-door-beneath-the-castle/source.json'
def main():
 d=json.loads(SOURCE.read_text());esc=html.escape
 c={'app':'DM Atlas','format':'dm-atlas-campaign','version':1,'id':'aurelion-the-door-beneath-the-castle','generated':'2026-10-16T00:00:00Z','title':'Aurelion — The Door Beneath the Castle','shortTitle':'Aurelion','system':'D&D 2024 rules (5.5e)','summary':'Rescue the missing mason Tomas Vale beneath Aurelion’s eastern foundations. Investigate the living roots, face the Ember-Root Crawler, and choose what to do about an ancient sealed door.','facts':{'Scenes':'47','Player visuals':'18','Maps':'7','Source books':'4'},'tabs':['overview','aurelion','sessions','npcs','locations','bestiary','items','tables','secrets','handbook'],'dmWarning':'Corrected Step 6 text and final DM correction panels take priority over older illustration text. Use the original PDFs at 100% / Actual Size for precise printed grids.','overview':[{'title':'Run this campaign','audience':'dm','html':'<p>Open the <b>Run Aurelion</b> tab for scene navigation, clues, latches, consequences, books and DM-controlled player visuals. Campaign switching uses Atlas’s existing separate party, combat and save system.</p><p>Use your existing party and assess encounter strength for its level. The supplied blank sheet is level 1; the illustrated cover refers to level 3. Do not automatically rescale the corrected Crawler stats.</p>'}], 'sessions':[],'npcs':[],'locations':[],'bestiary':[],'items':[],'tables':[],'secrets':[],'handbook':{'title':'Aurelion · Shared player display','lead':'Only scenes and maps explicitly revealed by the DM appear here.','sections':[{'id':'welcome','title':'The adventure','audience':'player','html':'<p>Your choices shape the adventure. Describe what your character tries; the DM tells you when a roll is needed.</p>'}]},'source':{'files':['Aurelion_The_Door_Beneath_the_Castle_DM_Guide_FINAL.pdf','Aurelion_The_Door_Beneath_the_Castle_Map_Character_Resource_Book.pdf','Aurelion_The_Door_Beneath_the_Castle_Shared_Player_Visual_Book.pdf','Aurelion_The_Door_Beneath_the_Castle_Step6_Illustrated_DM_Table_Play_Kit.pdf'],'note':'Author-supplied books; corrected table-kit text and DM final correction panels control adventure canon. Screen pages are optimized copies, not exact-size print masters.'},'art':{'folder':'art/aurelion-the-door-beneath-the-castle/','probe':d['assets']['players']['1'],'count':149},'aurelion':d}
 for i,sc in enumerate(d['scenes']):
  h='<div class="callout">'+esc(sc['note'])+'</div>'
  for ch in sc['checks']:h+='<p><b>'+esc(ch['skill'])+' · DC '+str(ch['dc'])+'</b><br>Success: '+esc(ch['success'])+'<br>Failure: '+esc(ch['failure'])+'</p>'
  h+='<p>Suggested next scenes: '+', '.join(d['scenes'][n]['id']+' '+esc(d['scenes'][n]['title']) for n in sc['next'])+'</p>'
  c['sessions'].append({'id':sc['id'],'number':i+1,'title':sc['id']+' — '+sc['title'],'summary':sc['note'],'scenes':[{'title':sc['title'],'html':h,'encounters':[{'enemies':'Ember-Root Crawler','tactics':'Fire resistance. Retreats at 6 HP or fewer; avoid downed PCs. Calm, retreat and environmental solutions are valid.','foes':[{'count':1,'name':'Ember-Root Crawler'}]}] if i==33 else []}]})
 for name,role,knows,secret in [('Lord Pyrrhos Emberthane','Master of Arms','Wants Tomas rescued discreetly. Knows ancient stonework and Ashen markings may connect to Ember Cores.','Does not know the living roots, hidden maintenance passage or what lies beyond the door.'),('Tomas Vale','Castle mason, age 32','First question: “Did you open the door?” Found the side passage, carved chamber and creature. AC 10, HP 4; avoids combat.','Cannot explain the root-and-flame system.'),('Lio Fen','Living Accord messenger','Warns against harming roots or giving Emberthane everything. Gives H-01 if accepted.','Does not name Tharion Greenward in the first meeting.'),('Sergeant Mara Venn','Guard','A castle worker disappeared. Loyal, disciplined, frightened.','Does not volunteer Emberthane’s private suspicions.'),('Orris Dane','Guard','Restrained, watchful and professional.','Offers little unless asked.')]:c['npcs'].append({'name':name,'role':role,'knows':knows,'secret':secret,'audience':'dm'})
 c['locations']=[{'name':r['name'],'html':'<p>Map '+r['id']+'. Suggested reveal at D-'+str(r['scene']).zfill(2)+'. Open Run Aurelion → Maps & visuals for individual map tiles.</p>','audience':'dm'} for r in d['resources'] if r.get('tiles')]
 c['bestiary']=[{'name':'Ember-Root Crawler','meta':'Campaign creature · use corrected custom statistics','ac':12,'hp':18,'init':'+1','speed':'25 ft.','res':'Fire','vul':'','imm':'','abilities':[[a,'',str(m),str(m)] for a,m in [('STR',2),('DEX',1),('CON',2),('INT',-3),('WIS',1),('CHA',-2)]],'lines':['Fire resistance. Retreats at 6 HP or fewer.','If ROOTS HARMED is recorded, it starts agitated.','Ember Spit: recharge 5–6. Track recharge manually.'],'sections':[{'title':'Actions','entries':[{'name':'Root Lash','text':'Melee Attack Roll: +4, reach 10 ft. Hit: 5 (1d6 + 2) Bludgeoning damage.'},{'name':'Ember Spit (Recharge 5–6)','text':'Ranged Attack Roll: +3, range 20/60 ft. Hit: 3 (1d6) Fire damage.'}]}]}, {'name':'Tomas Vale','meta':'Castle mason · avoids combat','ac':10,'hp':4,'init':'','speed':'Not specified in the source','abilities':[],'lines':['Avoids combat. No attacks are provided by the campaign.'],'sections':[]}]
 c['items']=[{'id':it['id'],'name':it['id']+' — '+it['name'],'type':'Campaign story item','text':it['text']} for it in d['items']]
 c['tables']=[{'title':'Corrected checks','columns':['Scene','Check','DC','Success','Failure'], 'rows':[[str(x['scene']).zfill(2),x['skill'],str(x['dc']),x['success'],x['failure']] for x in d['checks']]}]
 c['secrets']=[{'title':'Door, evidence and final consequences','html':'<p>All three latches are required at D-38. Opening the door at D-39 reveals only a gap of a few inches; an inner collapse blocks entry. H-04 is available only if it opens. Track who keeps each piece of evidence.</p><p>Rescuing Tomas: 10 gp and 75 XP per character, or use milestones instead of XP. Optional +10 XP each for the ancient warning, sparing the Crawler and rescuing Tomas without opening the door. Do not double-count rewards.</p><p>At D-45 meet Lio Fen, not a new High Steward. I-03 Verdant Favor grants one Advantage on a Nature, Survival or Animal Handling check. H-01 has the separate calming DC benefit.</p>'}]
 out=ROOT/'campaigns/aurelion-the-door-beneath-the-castle.dmatlas.json';out.write_text(json.dumps(c,ensure_ascii=False,indent=2)+'\n');(ROOT/'src/data/aurelion.js').write_text('/* Aurelion: author-supplied corrected campaign. Generated by tools/import_aurelion.py. */\nwindow.DM_BUNDLED_CAMPAIGNS = window.DM_BUNDLED_CAMPAIGNS || [];\nwindow.DM_BUNDLED_CAMPAIGNS.push('+json.dumps(c,ensure_ascii=False,separators=(',',':'))+');\n');print('Built Aurelion: 47 scenes, 5 NPCs, 7 maps, 149 book images.')
if __name__=='__main__':main()
